properties.query:
let lookback = 1h;
let binSize = 10m;
let MinDistinctRules = 8;
let MinDistinctUris = 15;
let MinHits = 40;
let AIAgentUA = dynamic(["GPTBot", "ChatGPT-User", "OAI-SearchBot", "ClaudeBot", "Claude-User", "Claude-SearchBot",
    "PerplexityBot", "Perplexity-User", "Meta-ExternalAgent", "Bytespider", "CCBot", "Google-Extended"]);
let AutomationUA = dynamic(["python-requests", "aiohttp", "httpx", "Go-http-client", "curl/", "Wget", "node-fetch",
    "axios", "HeadlessChrome", "Playwright", "puppeteer", "nuclei", "sqlmap"]);
let Bursts = AGWFirewallLogs
    | where TimeGenerated > ago(lookback)
    | where Action in ("Matched", "Blocked", "Detected")
    | summarize Hits = count(), DistinctRules = dcount(RuleId), DistinctUris = dcount(RequestUri),
                Rules = make_set(RuleId, 50), Messages = make_set(Message, 20), SampleUris = make_set(RequestUri, 20),
                Hosts = make_set(Hostname, 5), Actions = make_set(Action, 3)
             by ClientIp, Window = bin(TimeGenerated, binSize)
    | where DistinctRules >= MinDistinctRules and DistinctUris >= MinDistinctUris and Hits >= MinHits;
let UAContext = AGWAccessLogs
    | where TimeGenerated > ago(lookback)
    | where ClientIp in ((Bursts | project ClientIp))
    | summarize UserAgents = make_set(UserAgent, 10), Requests = count(),
                Status4xx = countif(HttpStatus between (400 .. 499)), Status5xx = countif(HttpStatus >= 500),
                Status2xx = countif(HttpStatus between (200 .. 299))
             by ClientIp;
let TI = ThreatIntelIndicators
    | where TimeGenerated > ago(14d) and IsActive == true
    | where ObservableKey has "ipv4-addr" or ObservableKey has "ipv6-addr"
    | summarize TIConfidence = max(Confidence) by ClientIp = ObservableValue;
Bursts
| join kind=leftouter UAContext on ClientIp
| join kind=leftouter TI on ClientIp
| extend UAText = tostring(UserAgents)
| extend ClaimsAIAgent = UAText has_any (AIAgentUA),
         AutomationClient = UAText has_any (AutomationUA),
         Got2xxDuringBurst = coalesce(Status2xx, 0) > 0 and Actions has "Matched"
| extend Severity = case(Got2xxDuringBurst or coalesce(TIConfidence, 0) >= 70, "High",
                         "Medium")
| project Window, ClientIp, Hits, DistinctRules, DistinctUris, Rules, Messages, SampleUris, Hosts, Actions, UserAgents,
          ClaimsAIAgent, AutomationClient, Requests, Status2xx, Status4xx, Status5xx, TIConfidence, Severity

let lookback = 7d;
let AIApiDomains = dynamic(["api.openai.com", "chatgpt.com", "api.anthropic.com", "claude.ai",
    "generativelanguage.googleapis.com", "aiplatform.googleapis.com", "api.mistral.ai", "api.deepseek.com",
    "api.x.ai", "api.perplexity.ai", "api.groq.com", "api.together.xyz", "openrouter.ai", "api.cohere.com",
    "huggingface.co", "api-inference.huggingface.co", "api.moonshot.cn", "dashscope.aliyuncs.com"]);
let Browsers = dynamic(["msedge.exe", "chrome.exe", "firefox.exe", "brave.exe", "opera.exe", "safari", "iexplore.exe",
    "msedgewebview2.exe"]);
let ApprovedProcesses = dynamic([]);
DeviceNetworkEvents
| where Timestamp > ago(lookback)
| where ActionType in ("ConnectionSuccess", "HttpConnectionInspected", "SslConnectionInspected")
| where isnotempty(RemoteUrl) and RemoteUrl has_any (AIApiDomains)
| where InitiatingProcessFileName !in~ (Browsers) and InitiatingProcessFileName !in~ (ApprovedProcesses)
| summarize Connections = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp),
            Destinations = make_set(RemoteUrl, 20), SampleCommandLines = make_set(InitiatingProcessCommandLine, 5),
            Parents = make_set(InitiatingProcessParentFileName, 5)
         by DeviceName, DeviceId, InitiatingProcessFileName, InitiatingProcessAccountUpn
| order by Connections desc

let Generated = format_datetime(now(), "yyyy-MM-dd HH:mm");
let Reg = YumaAIRegister();
let Total = toscalar(Reg | count);
let WithGaps = toscalar(Reg | where GapCount > 0 | count);
let ReviewDue = toscalar(Reg | where ReviewStatus in ("Overdue", "Never reviewed") | count);
let HighRisk = toscalar(Reg | where Flag_HighRiskPermissions | count);
let esc = (s:string) { replace_string(replace_string(s, "|", "/"), "\n", " ") };
let Head = datatable(Ord:long, Line:string) [
    0, "# AI agent register and ISM evidence summary",
    1, "",
    3, "",
    4, "Evidence supports an assessment. It is not a compliance determination. Statuses are computed from Microsoft Sentinel data; see controls.csv for metrics.",
    5, "",
    6, "## Register",
    7, ""
];
let Gen = print Ord = tolong(2), Line = strcat("Generated ", Generated, " UTC from Microsoft Sentinel workspace data.");
let RegLines = union
    (print Ord = tolong(8), Line = strcat("- Active agents and AI apps: ", Total)),
    (print Ord = tolong(9), Line = strcat("- Missing ISM-2135 fields: ", WithGaps)),
    (print Ord = tolong(10), Line = strcat("- Overdue or never reviewed (ISM-2138): ", ReviewDue)),
    (print Ord = tolong(11), Line = strcat("- Holding high-risk permissions (ISM-2156): ", HighRisk)),
    (print Ord = tolong(12), Line = ""),
    (print Ord = tolong(13), Line = "## ISM control evidence status"),
    (print Ord = tolong(14), Line = ""),
    (print Ord = tolong(15), Line = "| Control | Status | Metric | Evidence method |"),
    (print Ord = tolong(16), Line = "|---|---|---|---|");
let CtlLines = YumaISMControlStatus()
    | serialize Ord = tolong(100 + row_number())
    | project Ord, Line = strcat("| ", ControlId, " | ", Status, " | ", esc(Metric), " | ", EvidenceMethod, " |");
union Head, Gen, RegLines, CtlLines
| order by Ord asc
| summarize Lines = make_list(Line, 10000)
| project Markdown = strcat_array(Lines, "\n")
